var wg sync.WaitGroup

// Ошибка: Wait может вернуться до Add
for _, u := range urls {
    go func() {
        wg.Add(1)
        defer wg.Done()
        fetch(u)
    }()
}

// Go 1.25+
for _, u := range urls {
    wg.Go(func() { fetch(u) })
}
wg.Wait()

var loadConfig = sync.OnceValues(func() (*Config, error) {
    return parseConfig("config.yaml")
})

cfg, err := loadConfig()   // парсинг выполнится один раз
